import{_ as l,h as t,i as m,c as i,v as r,p as h,x as n,m as o,e as s,S as p}from"./chunks/framework.Dvtg8yj2.js";const b=JSON.parse('{"title":"波长台阶：g/i 线、KrF 248、ArF 193、EUV 13.5","description":"","frontmatter":{"title":"波长台阶：g/i 线、KrF 248、ArF 193、EUV 13.5","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/litho-wavelengths.md","filePath":"llm/litho-wavelengths.md","lastUpdated":1788454257000}'),d={name:"llm/litho-wavelengths.md"};function A(_,a,c,F,E,f){const e=t("Mermaid");return m(),i("div",null,[a[1]||(a[1]=r('<h1 id="波长台阶-g-i-线、krf-248、arf-193、euv-13-5" tabindex="-1">波长台阶：g/i 线、KrF 248、ArF 193、EUV 13.5 <a class="header-anchor" href="#波长台阶-g-i-线、krf-248、arf-193、euv-13-5" aria-label="Permalink to &quot;波长台阶：g/i 线、KrF 248、ArF 193、EUV 13.5&quot;">​</a></h1><div class="epigraph"><p>分辨率写成 $R=k_1\\lambda/\\mathrm{NA}$。波长不是连续旋钮，而是光源的属性：换一代波长，就要换光源、镜头材料与光刻胶。</p><footer>—— Chris A. Mack, Fundamental Principles of Optical Lithography, Wiley, 2007；讲义中的 Rayleigh 形式</footer></div><p>光学光刻的分辨率由 <a href="/llm/rayleigh-litho">瑞利判据</a> 给出：半节距 \\(R=k_1\\lambda/\\mathrm{NA}\\)。三项里，\\(\\mathrm{NA}\\) 可以在同一光源上缓慢抬高，\\(k_1\\) 可以靠照明、掩模与胶工艺往下压，唯独 \\(\\lambda\\) 不能微调。历史上每一次真正换波长，都是一次光源、投影光学与抗蚀剂的整栈替换。台阶依次是汞灯 g 线 436 nm、i 线 365 nm、KrF 准分子 248 nm、ArF 准分子 193 nm，再跳到 EUV 13.5 nm。本篇只讲这条波长轴：为什么是台阶、每一级换了什么、以及节点商品名为什么不能当成波长。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把 \\(\\lambda\\) 当成连续变量，缩短波长似乎永远比抬 \\(\\mathrm{NA}\\) 便宜：焦距深度 \\(\\mathrm{DOF}\\propto\\lambda/\\mathrm{NA}^2\\)，同样分辨率下短波更宽容。工业现实相反。可用的高强度、窄带宽、适合光学材料的谱线只有少数几条。汞弧灯的强线是 g（436 nm）、h（405 nm）与 i（365 nm）；再往短，连续谱强度不够，必须换准分子激光。准分子也不是任意波长：KrF 落在 248 nm，ArF 落在 193 nm。157 nm 的 \\(\\mathrm{F}_2\\) 激光曾被认真做过镜头与胶，最终因氟化钙双折射、薄膜与材料吸收而放弃。再下一步不是 157，而是跳过一个数量级到 13.5 nm。</p><p>因此问题不是「下一个小数点的纳米」，而是：在给定光源族里，光学与胶还能撑多久；撑不住时，下一档现成谱线是什么。把商品节点（28 nm、7 nm）直接读成曝光波长，会把整条物理轴读错。</p><h3 id="汞灯到准分子-材料窗口决定台阶" tabindex="-1">汞灯到准分子：材料窗口决定台阶 <a class="header-anchor" href="#汞灯到准分子-材料窗口决定台阶" aria-label="Permalink to &quot;汞灯到准分子：材料窗口决定台阶&quot;">​</a></h3><p>熔融石英在 i 线与 248 nm 仍可用；193 nm 已经要极低羟基的石英并小心吸收与致密化；157 nm 则把透射光学几乎逼到 \\(\\mathrm{CaF}_2\\)。Mack 把波长写成光源属性，意思是：谱线先被原子跃迁钉死，镜头玻璃再决定这条谱线能不能做成高 \\(\\mathrm{NA}\\) 投影物镜。胶同样不连续：g/i 线走重氮萘醌–酚醛（DNQ-novolak）；248 nm 起大规模改用化学放大胶（CAR），因为短波光子能量高、光源亮度与胶灵敏度必须重新匹配。换波长等于换化学。</p><p><span class="marginnote">h 线 405 nm 存在，但量产投影光刻的主台阶是 g 与 i。不要把灯谱上每一条峰都写成一代制程。KrF/ArF 的带宽要压到亚皮米量级，为的是控制色差与焦深，不是为了「更短一点」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把半节距写成</p> \\[R = k_1\\frac{\\lambda}{\\mathrm{NA}}. \\]<p>同一 \\(k_1\\) 与 \\(\\mathrm{NA}\\) 下，\\(\\lambda\\) 从 436 nm 降到 193 nm，理论半节距大约缩到 0.44 倍；从 193 nm 到 13.5 nm，再缩约 14 倍。实际从未单独吃这一项。g/i 线时代 \\(\\mathrm{NA}\\) 从约 0.3 抬到 0.6 量级，\\(k_1\\) 仍接近 0.6–0.8；KrF/ArF 把 \\(k_1\\) 推向 0.3 附近，干式 ArF 的 \\(\\mathrm{NA}\\) 约到 0.93；<a href="/llm/arf-immersion">浸没</a> 把 \\(\\mathrm{NA}\\) 做到 1.35。Mack 公开讲义里的对照是：波长大约 2.3 倍改善，\\(\\mathrm{NA}\\) 大约 8 倍，\\(k_1\\) 大约 3.5 倍，三者乘起来才把微米级半节距压到浸没单次曝光的极限附近。</p><p>EUV 的 13.5 nm 不是「再短一档准分子」，而是 Mo/Si 多层膜布拉格反射的工作带。真空、全反射、等离子体光源，都在波长选定之后才成为约束。波长台阶在这里同时改了光学拓扑：透射镜头结束，反射镜头开始。</p><h3 id="单次曝光的波长极限" tabindex="-1">单次曝光的波长极限 <a class="header-anchor" href="#单次曝光的波长极限" aria-label="Permalink to &quot;单次曝光的波长极限&quot;">​</a></h3><p>浸没 ArF 在 \\(k_1=0.25\\) 的两束成像极限下，半节距 \\(R=0.25\\times 193/1.35\\approx 36\\,\\mathrm{nm}\\)。Mack 给出的实用单次曝光半节距大约 38–40 nm，对应最小节距约 75–80 nm。再往下不是换 157 nm，而是 <a href="/llm/lele-multipattern">LELE</a>、<a href="/llm/sadp-saqp">SADP/SAQP</a> 把一次曝光分解成多次，或换 EUV。波长轴在 193 nm 干/浸没处停住，不是因为没有更短的光子，而是因为下一档透射光学没有工业解。</p>',16)),(m(),h(p,null,{default:n(()=>[s(e,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22g%20%E7%BA%BF%20436%20nm%22%5D%20--%3E%20I%5B%22i%20%E7%BA%BF%20365%20nm%22%5D%0A%20%20I%20--%3E%20KRF%5B%22KrF%20248%20nm%22%5D%0A%20%20KRF%20--%3E%20ARF%5B%22ArF%20193%20nm%20%E5%B9%B2%E5%BC%8F%22%5D%0A%20%20ARF%20--%3E%20IMM%5B%22ArF%20%E6%B5%B8%E6%B2%A1%20NA%201.35%22%5D%0A%20%20IMM%20--%3E%20MP%5B%22%E5%A4%9A%E9%87%8D%E5%9B%BE%E5%BD%A2%20%2F%20EUV%2013.5%20nm%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每一级台阶绑定三类硬件。光源：汞灯的 i 线强度足够支撑步进机；KrF/ArF 准分子以脉冲运转，重复频率与能量剂量控制进入曝光剂量方程。投影光学：波长决定折射率、吸收与镀膜，从而决定能做多大的 \\(\\mathrm{NA}\\) 与多重镀膜的寿命。抗蚀剂：吸收系数必须让光在胶厚方向形成可显影的潜像，又不能在表面就把能量吃光。三者同时换代，所以产线表现为「台阶」而不是连续缩短。</p><p>离轴照明与相移掩模不改 \\(\\lambda\\)，只改 \\(k_1\\)。它们能把 193 nm 继续往下用很多代，但改变不了瑞利公式里 \\(\\lambda\\) 这一项。EUV 把 \\(\\lambda\\) 砍掉一个数量级，单次曝光的 \\(k_1\\) 预算重新变宽；DUV 则把同一 \\(\\lambda\\) 用多重曝光「借用」空间频率。两条路都承认：193 nm 已经是透射光学的终点波长。</p><p><span class="marginnote">不要把「7 nm 节点」读成 \\(\\lambda=7\\,\\mathrm{nm}\\)。商品节点是晶体管密度与设计规则的市场名，金属半节距、鳍节距与曝光波长是三张不同的尺。波长史只对光源谱线负责。</span></p><h3 id="放弃-157-nm-说明了什么" tabindex="-1">放弃 157 nm 说明了什么 <a class="header-anchor" href="#放弃-157-nm-说明了什么" aria-label="Permalink to &quot;放弃 157 nm 说明了什么&quot;">​</a></h3><p>157 nm 在纸面上介于 193 与 13.5 之间，似乎能平滑过渡。工业上它要求几乎全 \\(\\mathrm{CaF}_2\\) 的镜头、新的薄膜、新的胶，以及仍然不够的 \\(\\mathrm{NA}\\) 与焦深收益。浸没水在 193 nm 的折射率约 1.44，把 \\(\\mathrm{NA}\\) 抬到 1.35，分辨率收益超过改 157 nm 干式，且能沿用 193 nm 胶与部分掩模基建。选择停在 193 再跳 EUV，是材料与供应链的决策，不是光谱学上没有 157 这条线。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>波长台阶不能解释套刻、缺陷与产能。同一 193 nm 浸没机台，既可以做 45 nm 级单次曝光，也可以给 7/5 nm 级做多重图形的「非 EUV 层」。规划产能时，层数与 <a href="/llm/twinscan-dual-stage">双工件台</a> 吞吐比波长更先到达成本账。EUV 的 13.5 nm 解决的是临界层的空间频率，不自动取消 DUV：后道、植入、较松的金属仍大量留在 248/193。</p><p>也不要把光源带宽、偏振与波长混为一谈。ArF 激光的带宽控制是色差与焦深问题；EUV 的带宽由多层膜反射通带决定。两者都叫「谱」，约束完全不同。引用分辨率数字时，必须同时给出 \\(k_1\\)、\\(\\mathrm{NA}\\) 与照明（偶极还是常规），否则 \\(\\lambda\\) 单独出现只是半句话。</p><p><span class="marginnote">本篇不引用任何工艺节点的良率百分比。波长史是光谱与材料史。良率是缺陷、套刻、随机效应与产线控制的结果，不能从 \\(\\lambda\\) 直接读出。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光刻波长按光源台阶走：g 线 436 nm、i 线 365 nm、KrF 248 nm、ArF 193 nm、EUV 13.5 nm，不是连续可调。</li><li>瑞利公式里 \\(\\lambda\\) 与 \\(\\mathrm{NA}\\)、\\(k_1\\) 并列；历史上 \\(\\mathrm{NA}\\) 与 \\(k_1\\) 的贡献不小于缩短波长。</li><li>157 nm 未成为量产台阶；浸没 193 nm 把透射光学用到 \\(\\mathrm{NA}=1.35\\)。</li><li>单次浸没曝光的实用半节距约 38–40 nm 量级，更密要靠多重图形或 EUV。</li><li>商品节点名不是曝光波长；不要把 7 nm 读成 7 nm 光子。</li><li>换波长等于换光源、镜头材料与胶化学，所以表现为代际跳跃。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>, Wiley, 2007；ASML 公开产品页对 193 nm 浸没与 13.5 nm EUV 的波长陈述。</li></ul>',12))])}const u=l(d,[["render",A]]);export{b as __pageData,u as default};
